const Redis = require('ioredis');
const logger = require('../utils/logger');

const preferMemory = (process.env.CACHE_DRIVER || '').toLowerCase() === 'memory'
  || process.env.NODE_ENV === 'test';

let client = null;
let connected = false;

function sanitizeRedisUrl(rawUrl) {
  try {
    const parsed = new URL(rawUrl);
    if (parsed.password) parsed.password = '***';
    if (parsed.username) parsed.username = parsed.username ? '***' : '';
    return parsed.toString();
  } catch (_) {
    return 'redis://<configured>';
  }
}

function isRedisEnabled() {
  return !preferMemory && process.env.CACHE_ENABLED !== 'false';
}

function getClient() {
  if (!isRedisEnabled()) {
    return null;
  }

  if (!client) {
    const redisUrl = process.env.REDIS_URL || 'redis://127.0.0.1:6379';
    client = new Redis(redisUrl, {
      enableReadyCheck: true,
      connectTimeout: parseInt(process.env.REDIS_CONNECT_TIMEOUT || '5000', 10),
      lazyConnect: false,
      maxRetriesPerRequest: parseInt(process.env.REDIS_MAX_RETRIES || '2', 10),
    });

    client.on('connect', () => {
      connected = true;
      logger.info('Redis: connected', { url: sanitizeRedisUrl(redisUrl) });
    });

    client.on('error', (error) => {
      connected = false;
      logger.error('Redis: connection error', { error: error.message });
    });

    client.on('end', () => {
      connected = false;
      logger.warn('Redis: connection closed');
    });
  }

  return client;
}

function isMemoryFallback() {
  return preferMemory;
}

function isConnected() {
  return connected;
}

module.exports = {
  getClient,
  isRedisEnabled,
  isMemoryFallback,
  isConnected,
};
